begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.fi(t text) returns uuid language sql immutable as $$select md5('ministry-media-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fi(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.fi(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-family@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','second','outside','unconfirmed'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.fi('org'),'Famílias fictícias','ministry-media-test','active'),(pg_temp.fi('outsideorg'),'Outro fictício','media-outside','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.fi('a'),pg_temp.fi('org'),'Sede fictícia','a','headquarters'),(pg_temp.fi('b'),pg_temp.fi('org'),'Filial fictícia','b','campus');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) select pg_temp.fi(t||'-membership'),pg_temp.fi('org'),pg_temp.fi(t),pg_temp.fi('a'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member','second','unconfirmed'])t;
insert into public.people(id,organization_id,unit_id,auth_user_id,full_name,status,birth_date) select pg_temp.fi(t||'-person'),pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi(t),t||' pessoa fictícia','active',current_date-interval '35 years' from unnest(array['owner','member','second','unconfirmed'])t;

create function pg_temp.admin(a text,v integer default null,d jsonb default '{}',i uuid default pg_temp.fi('video')) returns jsonb language sql as $$select public.ministry_media_admin(pg_temp.fi('org'),pg_temp.fi('a'),a,i,v,d)$$;
create function pg_temp.catalog(u text default 'a') returns jsonb language sql as $$select public.member_media(pg_temp.fi('org'),pg_temp.fi(u))$$;
create function pg_temp.self(a text,d jsonb default '{}') returns jsonb language sql as $$select public.member_media_self(pg_temp.fi('org'),pg_temp.fi('a'),a,pg_temp.fi('video'),d)$$;
select ok(not has_table_privilege('authenticated','private.ministry_media_progress','select'),'progress is private');
select ok(not has_table_privilege('anon','private.kids_operational_notes','select'),'Kids notes never public');
select ok(not has_function_privilege('anon','public.kids_notes(uuid,uuid,uuid,text,uuid,integer,jsonb)','execute'),'no anonymous notes');
set local role authenticated;select pg_temp.actor('member');
select throws_ok($$select pg_temp.admin('save',0,'{"kind":"video"}')$$,'42501','media_denied','member cannot publish');
select pg_temp.actor('owner');
select lives_ok($$select pg_temp.admin('save',0,'{"kind":"video","title":"Vídeo fictício","source":"https://example.com/video.mp4","download":false}')$$,'draft created');
select is(jsonb_array_length(pg_temp.catalog()->'items'),0,'draft hidden');
select lives_ok($$select pg_temp.admin('publish',1)$$,'publish draft');
select is(jsonb_array_length(pg_temp.catalog()->'items'),1,'published video visible');
select is(jsonb_array_length(pg_temp.catalog('b')->'items'),0,'other church does not receive video');
select throws_ok($$select pg_temp.admin('archive',1)$$,'40001','media_changed','stale version blocked');
select throws_ok($$select public.ministry_media_admin(pg_temp.fi('org'),pg_temp.fi('b'),'archive',pg_temp.fi('video'),2)$$,'42501','media_denied','cannot move content across units');
select lives_ok($$select pg_temp.admin('opening',0,'{"kind":"image","url":"https://example.com/opening.jpg","title":"Bem-vindo","seconds":3}',null)$$,'opening saved');
select throws_ok($$select pg_temp.admin('opening',0,'{"kind":"none","title":"","seconds":3}',null)$$,'40001','media_changed','opening optimistic revision');
select throws_ok($$select pg_temp.admin('opening',1,'{"kind":"video","url":"https://example.com/opening.html","seconds":3}',null)$$,'22023','invalid_media','opening requires MP4 video');
select pg_temp.actor('member');
select lives_ok($$select pg_temp.self('progress','{"position":30,"favorite":true,"version":2}')$$,'own progress saved');
select is((pg_temp.self('history')->'items'->0->>'position_seconds')::integer,30,'resume position');
select throws_ok($$select pg_temp.self('progress','{"position":30,"favorite":true,"version":1}')$$,'40001','media_changed','stale media progress denied');
select throws_ok($$select pg_temp.self('download')$$,'42501','media_denied','unauthorized download denied');
select pg_temp.actor('second');select is(jsonb_array_length(pg_temp.self('history')->'items'),0,'another user has no history');
select pg_temp.actor('outside');select throws_ok($$select pg_temp.self('history')$$,'42501','community_denied','outsider denied');
select pg_temp.actor('unconfirmed');select throws_ok($$select pg_temp.self('history')$$,'42501',null,'unconfirmed denied');
select pg_temp.actor('owner');select lives_ok($$select pg_temp.admin('archive',2)$$,'archive publication');
select pg_temp.actor('member');select is(jsonb_array_length(pg_temp.self('history')->'items'),0,'archived hidden from history');
reset role;set local role anon;
select is(jsonb_array_length(pg_temp.catalog()->'items'),0,'anonymous catalog hides archive');
select is(public.member_app_opening(pg_temp.fi('org'))->>'kind','image','opening contains only public brand data');
select throws_ok($$select public.member_media(pg_temp.fi('org'),pg_temp.fi('a'),'video',-1)$$,'22023','invalid_media','invalid pagination blocked');
reset role;
select * from finish();rollback;
